function available(){const search=$('asset-search').value.toLowerCase();return ASSETS.filter(a=>(category==='All'||a.category===category)&&(preset==='all'||a.usedBy.includes(preset))&&`${a.name} ${a.category} ${a.notes}`.toLowerCase().includes(search));}
