function showAssembly(id){const a=ASSEMBLIES.find(p=>p.id===id);preset=id;select.value=id;renderList();assemblyMode=true;history.replaceState(null,'',`#amp/${id}`);document.querySelectorAll('#asset-list button').forEach(b=>b.setAttribute('aria-pressed',false));$('object-kind').textContent='COMPLETE ASSEMBLY';$('dimension-label').textContent='CABINET DIMENSIONS / REFERENCE STUDY';$('record-category').textContent=a.example.toUpperCase();$('record-name').textContent=a.name;$('record-status').textContent='Reference assembly · work in progress';$('record-description').textContent='Built from the same materials, controls, badges and speaker components inspected in this library. Cabinet measurements and component placements still require a measured vintage specimen.';$('texture-tools').hidden=true;details([['Cabinet W × H × D',`${a.dimensionsMm.map(v=>Number(v.toFixed(1))).join(' × ')} mm`],['Dimension basis',a.dimensionsStatus],['Speakers',`${a.speakerCount} × ${assetById(a.speaker).name}`],['Wiring',a.wiring],['Resulting load',`${Number(a.loadOhm.toFixed(2))} Ω`],['Controls',`${a.knobCount} × ${assetById(a.knob).name}`],...(a.tubeTypes?[["Tube lineup",a.tubeTypes.join(' · ')],["Rectifier evidence",a.rectifierBasis]]:[]),['Pilot indicator',a.jewel==='jewel-green'?'Green jewel':a.jewel==='pilot-led-red'?'Small red LED':'Red jewel'],['Faceplate',assetById(a.panel).name],['Grille badge',a.badge?assetById(a.badge).name:'None on selected reference']]);sources(a.sources);$('uses-heading').textContent='Assembly components';$('record-uses').replaceChildren();for(const [component,n] of [[a.speaker,a.speakerCount],[a.cover,1],[a.cloth,1],[a.knob,a.knobCount],[a.handle,a.caster?2:1],[a.badge,1],[a.panel,1],[a.jewel,1],...(a.caster?[['caster-snap-in-study',4]]:[])]){if(!component)continue;const b=document.createElement('button');b.className='uses-button';b.textContent=`${n} × ${assetById(component).name}`;b.onclick=()=>{category='All';$('asset-search').value='';renderList();showAsset(component);};$('record-uses').append(b);}display(()=>createAmpModel(a),'angle');}
$('show-assembly').onclick=()=>showAssembly(preset==='all'?'deluxe-5e3':preset);
function download(blob,name){if(!blob)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('download-catalog').onclick=()=>download(new Blob([JSON.stringify({version:'0.1',units:'mm',sources:SOURCES,components:ASSETS,assemblies:ASSEMBLIES},null,2)],{type:'application/json'}),'amplifier-component-library-v0.1.json');
$('export-model').onclick=async()=>{const button=$('export-model');button.disabled=true;$('export-status').textContent='Preparing model…';let object;try{await readyForExport();const id=assemblyMode?(preset==='all'?'deluxe-5e3':preset):activeId;object=assemblyMode?createAmpModel(ASSEMBLIES.find(a=>a.id===id)):createComponent(id);object.scale.setScalar(assemblyMode?.001/MM:.001);object.userData={...object.userData,libraryId:id,libraryVersion:'0.1',units:'metres',accuracy:'Reference study; see component catalog for source provenance and estimated geometry.'};const exportScene=new THREE.Scene();exportScene.add(object);const {GLTFExporter}=await import('../vendor/GLTFExporter.js');const bytes=await new GLTFExporter().parseAsync(exportScene,{binary:true,maxTextureSize:4096});download(new Blob([bytes],{type:'model/gltf-binary'}),`${id}.glb`);$('export-status').textContent='GLB exported with materials. Model units: metres.';}catch(error){console.error(error);$('export-status').textContent='The model could not be exported. Please try again.';}finally{if(object)disposeObject(object);button.disabled=false;}};
function display(make,view){if(!renderer)return;try{if(root){scene.remove(root);disposeObject(root);}camera.fov=!assemblyMode&&activeId==='knob-skirted'?20:35;camera.updateProjectionMatrix();root=new THREE.Group();const object=make();root.add(object);const bounds=new THREE.Box3().setFromObject(object),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3()),scale=3.7/Math.max(size.x,size.y,size.z);object.position.sub(center);root.scale.setScalar(scale);scene.add(root);controls.target.set(0,0,0);setView(view);}catch(error){console.error(error);$('viewer-error').hidden=false;}}
function setView(name){if(!camera)return;for(const [id,view] of [['view-front','front'],['view-rear','rear'],['view-angle','angle']])$(id).setAttribute('aria-pressed',view===name);spin=false;controls.autoRotate=false;$('motion').textContent='Rotate';$('motion').setAttribute('aria-pressed',false);const lens=Math.tan(35*Math.PI/360)/Math.tan(camera.fov*Math.PI/360);camera.position.set(...(name==='front'?[0,0,7.7]:name==='rear'?[0,0,-7.7]:[4,2.5,6.5])).multiplyScalar(lens);controls.update();}
