try{const host=$('part-viewport');renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;host.append(renderer.domElement);scene=new THREE.Scene();const environment=studioEnvironment(renderer);scene.environment=environment.texture;scene.environmentIntensity=.8;scene.add(new THREE.HemisphereLight('#d5e1e9','#35352d',1.7));for(const [pos,power,color] of [[[3,5,6],3,'#fff0da'],[[-4,1,-3],2,'#adc5dc']]){const l=new THREE.DirectionalLight(color,power);l.position.set(...pos);scene.add(l);}camera=new THREE.PerspectiveCamera(35,1,.01,100);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.minDistance=3.7;controls.maxDistance=15;controls.autoRotateSpeed=.4;controls.addEventListener('start',()=>{spin=false;controls.autoRotate=false;$('motion').textContent='Rotate';$('motion').setAttribute('aria-pressed',false);});const resize=()=>{const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();};new ResizeObserver(resize).observe(host);resize();host.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','+','-'].includes(e.key))return;e.preventDefault();const offset=camera.position.clone();if(e.key==='ArrowLeft'||e.key==='ArrowRight')offset.applyAxisAngle(new THREE.Vector3(0,1,0),e.key==='ArrowLeft'?.15:-.15);else offset.multiplyScalar(e.key==='+'?.9:1.1);camera.position.copy(offset.clampLength(3.7,15));controls.update();};function frame(time){requestAnimationFrame(frame);if(document.hidden)return;if(time-last<32&&!spin)return;last=time;controls.update();renderer.render(scene,camera);}requestAnimationFrame(frame);window.addEventListener('pagehide',()=>{environment.dispose();renderer.dispose();controls.dispose();if(root)disposeObject(root);},{once:true});}catch(error){console.error(error);$('viewer-error').hidden=false;}
